import groovy.json.JsonOutput
import groovy.json.JsonSlurper
import java.security.MessageDigest

def flowFile = session.get()
if (flowFile == null) return
def text = ''
session.read(flowFile, { input -> text = input.getText('UTF-8') } as InputStreamCallback)
def parsed = new JsonSlurper().parseText(text)
def row = (parsed instanceof List && !parsed.isEmpty()) ? parsed[0] : (parsed instanceof Map ? parsed : [:])
def site = (row.site_id ?: row.Site ?: row.DEVICE ?: row['Device Name'] ?: row['System Name'] ?: row.node_id ?: '').toString().trim()
def ext = (row.external_alarm_id ?: row.AlarmID ?: row['Alarm ID'] ?: row['Event ID'] ?: row.SERIAL_NO ?: '').toString().trim()
def description = (row.event_description ?: row.Event ?: row.ALARM_TYPE ?: row['Event Name'] ?: row.SpecificProblem ?: row['Alarm Name'] ?: '').toString().trim()
def objectName = (row.object ?: row.Object ?: row.OEM ?: row.Slot_Port ?: '').toString().trim()
def now = new Date().format("yyyy-MM-dd'T'HH:mm:ss'Z'", TimeZone.getTimeZone('UTC'))
def raised = (row.source_event_time ?: row.Raised ?: row.RAISED ?: row['Raised At'] ?: row.Date ?: now).toString().trim()
def clearedRaw = (row.Cleared ?: row.CLEARED ?: row['Cleared At'] ?: '').toString().trim()
def cleared = (clearedRaw == '-' || clearedRaw == 'null' || clearedRaw == '') ? null : clearedRaw
def stateRaw = (row.State ?: row.ALARM_STATUS ?: '').toString().trim()
def isClear = stateRaw.toLowerCase().contains('clear') || stateRaw.toLowerCase().contains('inactive') || cleared != null
def state = isClear ? 'cleared' : (stateRaw.toLowerCase().contains('ack') ? 'acknowledged' : 'active')
def eventType = isClear ? 'clear' : 'raise'
def sevRaw = (row.Severity ?: row.SEVERITY ?: 'indeterminate').toString().trim().toLowerCase()
def severity = isClear ? 'cleared' : sevRaw
if (!(severity in ['critical','major','minor','warning','indeterminate','cleared'])) severity = 'indeterminate'
def vendor = (flowFile.getAttribute('X-Vendor') ?: row.OEM ?: row.vendor ?: 'aviat').toString().trim().toLowerCase()
if (!(vendor in ['aviat','cambium','radwin','ceragon'])) vendor = 'aviat'
def alarmKey = vendor + ':' + site + ':' + (ext ?: 'unknown')
def identity = [alarm_key: alarmKey, event_type: eventType, state: state, severity: severity, raised: raised, cleared: cleared, event: description, object: objectName]
def digest = MessageDigest.getInstance('SHA-256').digest(JsonOutput.toJson(identity).getBytes('UTF-8')).encodeHex().toString()
def sourceFile = flowFile.getAttribute('X-Original-Filename') ?: flowFile.getAttribute('http.headers.x-original-filename') ?: flowFile.getAttribute('filename') ?: 'unknown.csv'
def sourceRowText = flowFile.getAttribute('X-Row-Number') ?: flowFile.getAttribute('http.headers.x-row-number') ?: '1'
def sourceRow = sourceRowText.isInteger() ? sourceRowText.toInteger() : 1
def streamId = flowFile.getAttribute('X-Stream-Id') ?: flowFile.getAttribute('X-Stream-ID') ?: flowFile.getAttribute('http.headers.x-stream-id') ?: flowFile.getAttribute('stream_id') ?: ''
def replayCycleId = flowFile.getAttribute('X-Replay-Cycle-Id') ?: flowFile.getAttribute('X-Replay-Cycle-ID') ?: flowFile.getAttribute('http.headers.x-replay-cycle-id') ?: flowFile.getAttribute('replay_cycle_id') ?: ''
def replaySequenceText = flowFile.getAttribute('X-Replay-Sequence') ?: flowFile.getAttribute('http.headers.x-replay-sequence') ?: sourceRowText
def replaySequence = replaySequenceText.isInteger() ? replaySequenceText.toInteger() : null
def out = [schema_version: 1, contract: 'noc-alarm-mapped.v1', vendor: vendor, source_system: context.getProperty('Source System').evaluateAttributeExpressions(flowFile).getValue(), source_file: sourceFile, source_row: sourceRow, event_id: 'sha256:' + digest, alarm_key: alarmKey, external_alarm_id: ext ?: vendor + '-' + digest[0..23], event_description: description, object: objectName, site_id: site, node_id: site ?: null, severity: severity, state: state, event_type: eventType, canonical_category: 'UNKNOWN', probable_cause_raw: row.ProbableCause ?: description, specific_problem: row.SpecificProblem ?: '', source_event_time: raised, effective_event_time: (isClear ? cleared : raised), device_raised_at: row.device_raised_at, device_cleared_at: row.device_cleared_at, nms_cleared_at: cleared, ingested_at: now, trace_id: 'http:' + sourceFile + ':' + sourceRow, stream_id: streamId, replay_cycle_id: replayCycleId, replay_sequence: replaySequence, Circle: site.size() > 1 ? site[0..1] : site, Cleared: cleared, SpecificProblem: row.SpecificProblem ?: '', ProbableCause: row.ProbableCause ?: description, AlarmID: ext ?: vendor + '-' + digest[0..23], Site: site, Severity: severity.capitalize(), State: isClear ? 'Cleared by network' : state.capitalize(), AlarmName: description, Raised: raised]
flowFile = session.write(flowFile, { output -> output.write(JsonOutput.toJson(out).getBytes('UTF-8')) } as OutputStreamCallback)
flowFile = session.putAttribute(flowFile, 'replay_cycle_id', (replayCycleId ?: '').toString())
flowFile = session.putAttribute(flowFile, 'event_id', ('sha256:' + digest).toString())
flowFile = session.putAttribute(flowFile, 'alarm_key', alarmKey.toString())
flowFile = session.putAttribute(flowFile, 'external_alarm_id', (ext ?: vendor + '-' + digest[0..23]).toString())
flowFile = session.putAttribute(flowFile, 'vendor', vendor.toString())
flowFile = session.putAttribute(flowFile, 'source_file', (sourceFile ?: '').toString())
flowFile = session.putAttribute(flowFile, 'source_row', sourceRow.toString())
session.transfer(flowFile, REL_SUCCESS)
